    <div id="content">
        <div class="loading">正在打印活体检疫吊牌...</div>
    </div>

    <script>
        /* ========== 获取消息内容 ========== */
        function getMessageData() {
            var chatMessages = getChatMessages(getCurrentMessageId());
            if (!chatMessages || chatMessages.length === 0) {
                return null;
            }
            return chatMessages[0].message;
        }

        /* ========== 解析数据 ========== */
        function parseData(messageText) {
            var result = {};
            var tagMatch = messageText.match(/<meat_id>([\s\S]*?)<\/meat_id>/);

            if (!tagMatch || !tagMatch[1]) {
                return null;
            }

            var content = tagMatch[1];
            var regex = /\[([^|\]]+)\|([^\]]+)\]/g;
            var match;

            while ((match = regex.exec(content)) !== null) {
                var key = match[1].trim();
                var value = match[2].trim();
                result[key] = value;
            }

            return result;
        }

        /* ========== 渲染界面 ========== */
        function renderPage(data) {
            if (!data) {
                document.getElementById('content').innerHTML = '<div class="loading">❌ 标签数据解析失败</div>';
                return;
            }

            var html = '<div class="id-card-container">';

            /* 头部 */
            html += '<div class="id-card-header">';
            html += '<div class="hole"></div>';
            html += '<div class="title">活体生肉检疫吊牌</div>';
            html += '<div class="barcode"></div>';
            html += '<div style="font-family: monospace; font-size: 12px; margin-top: -5px;">NO.' + (data['出厂编号'] || 'UNKNOWN') + '</div>';
            html += '</div>';

            /* 主体数据 */
            html += '<div class="id-card-body">';

            /* 基础检疫信息 */
            html += '<div class="section-title">基础检疫信息</div>';
            var baseFields = ['商品品种', '体型年龄', '活体状态', '核心参数', '附加特征'];
            for (var i = 0; i < baseFields.length; i++) {
                var field = baseFields[i];
                var val = data[field] || '未录入';
                html += '<div class="data-row">';
                html += '<div class="data-label">' + field + '</div>';
                html += '<div class="data-value">' + val + '</div>';
                html += '</div>';
            }

            /* 活体外貌锚点 */
            html += '<div class="section-title" style="margin-top: 12px;">活体外貌锚点</div>';
            var anchorFields = ['三围数据', '肤色质感', '发色瞳色', '乳房私处'];
            for (var j = 0; j < anchorFields.length; j++) {
                var field2 = anchorFields[j];
                var val2 = data[field2] || '未录入';
                html += '<div class="data-row">';
                html += '<div class="data-label">' + field2 + '</div>';
                html += '<div class="data-value">' + val2 + '</div>';
                html += '</div>';
            }

            html += '</div>';

            /* 印章判断 */
            var status = data['检疫结果'] || '';
            if (status.indexOf('合格') !== -1) {
                html += '<div class="stamp"></div>';
            } else {
                html += '<div class="stamp" style="color: #555; border-color: #555; opacity: 0.6;"><span style="font-size:14px; transform:rotate(15deg); display:block;">残次废品</span></div>';
            }

            html += '</div>';

            document.getElementById('content').innerHTML = html;
        }

        /* ========== 主函数 ========== */
        function init() {
            try {
                var messageText = getMessageData();
                if (!messageText) {
                    document.getElementById('content').innerHTML = '<div class="loading">❌ 无法获取消息内容</div>';
                    return;
                }
                var data = parseData(messageText);
                renderPage(data);
            } catch (error) {
                document.getElementById('content').innerHTML = '<div class="loading">❌ 加载出错</div>';
            }
        }

        $(function() { init(); });
    </script>
</body>
</html>
