    <script>
        /* ========== 获取消息内容 ========== */
        function getMessageData() {
            var chatMessages = getChatMessages(getCurrentMessageId());
            if (!chatMessages || chatMessages.length === 0) {
                return null;
            }
            return chatMessages[0].message;
        }

        /* ========== 解析数据 ========== */
        function parseData(messageText) {
            var result = {};
            var tagMatch = messageText.match(/<meat_description_sheet>([\s\S]*?)<\/meat_description_sheet>/);

            if (!tagMatch || !tagMatch[1]) {
                return null;
            }

            var content = tagMatch[1];
            var regex = /\[([^|\]]+)\|([^\]]+)\]/g;
            var match;

            while ((match = regex.exec(content)) !== null) {
                var key = match[1].trim();
                var value = match[2].trim();
                result[key] = value;
            }

            return result;
        }

        /* ========== 格式化为纯文本供复制 ========== */
        function formatForCopy(data) {
            var text = "【活体女肉锚点数据】\n";
            text += "--- 基础规格 ---\n";
            text += "出厂编号: " + (data['出厂编号'] || '无') + "\n";
            text += "种族品种: " + (data['种族品种'] || '无') + "\n";
            text += "体型年龄: " + (data['体型年龄'] || '无') + "\n";
            text += "身高净重: " + (data['身高净重'] || '无') + "\n";
            text += "包装状态: " + (data['包装状态'] || '无') + "\n\n";

            text += "--- 外貌与肉体特征 ---\n";
            text += "三围数据: " + (data['三围数据'] || '无') + "\n";
