            html += '<div class="section-title">活体状态与加工</div>';
            html += '<div class="data-list">';
            var extraFields = ['活体特征', '体表瑕疵', '特殊处理'];
            for (var k = 0; k < extraFields.length; k++) {
                var field3 = extraFields[k];
                html += '<div class="data-item"><div class="item-label">' + field3 + '</div><div class="item-value">' + (data[field3] || '未记录') + '</div></div>';
            }
            html += '</div>';

            /* 隐藏域保存文本 */
            html += '<textarea id="raw-data" style="display:none;">' + rawText + '</textarea>';

            /* 动作区 */
            html += '<div class="action-area">';
