  .meat-status { background: #551111; color: #ffcccc; padding: 2px 6px; border-radius: 2px; font-size: 11px; border: 1px solid #330000;}
  .meat-info { padding: 8px; font-size: 12px; line-height: 1.6; }
  .info-line { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 3px; border-bottom: 1px dashed rgba(0,0,0,0.1); padding-bottom: 2px;}
  .info-label { color: #555; font-weight: bold; }

  .action-panel { background: #0a0a0a; border: 2px solid #222; border-top: 4px solid #441111; border-radius: 2px; padding: 10px; margin-top: 10px; box-shadow: inset 0 0 15px rgba(0,0,0,0.8); }
  .panel-title { color: #888; font-size: 13px; font-weight: bold; margin-bottom: 10px; background: #111; padding: 4px 8px; border: 1px solid #222;}
  .panel-title span.target { color: #ff5555; font-family: monospace; font-size: 14px;}
  .btn-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; }

  .btn { padding: 8px 6px; font-weight: bold; font-family: inherit; font-size: 11px; cursor: pointer; border-radius: 2px; text-shadow: -1px -1px 1px rgba(0,0,0,0.5); transition: all 0.1s; border: 1px solid #000; text-align: center; }
  .btn:active { transform: translateY(2px); box-shadow: inset 0 2px 4px rgba(0,0,0,0.8); }
  .btn-blue { background: linear-gradient(to bottom, #335577, #112233); color: #cceeff; box-shadow: 0 3px 0 #001122; }
  .btn-red { background: linear-gradient(to bottom, #aa3333, #661111); color: #ffcccc; box-shadow: 0 3px 0 #330000; }
  .btn-yellow { background: linear-gradient(to bottom, #aa8833, #554411); color: #ffeecc; box-shadow: 0 3px 0 #221100; }
  .btn-gray { background: linear-gradient(to bottom, #555, #222); color: #bbb; box-shadow: 0 3px 0 #000; }
  .btn-purple { background: linear-gradient(to bottom, #6633aa, #331166); color: #ffccff; box-shadow: 0 3px 0 #1a0033; }

  /* ================= TAB 2: 终端生成机 ================= */
  .terminal-box { background: #030503; border: 4px ridge #1a2a1a; border-radius: 2px; padding: 12px; box-shadow: inset 0 0 40px rgba(0,255,0,0.05), 0 5px 15px rgba(0,0,0,0.8); }
  .screen { background: #020802; border: 2px inset #0a1a0a; padding: 10px; margin-bottom: 12px; color: #00ff00; font-family: 'Courier New', monospace; font-size: 12px; font-weight: bold; text-shadow: 0 0 3px rgba(0,255,0,0.6); }

  .config-list { display: flex; flex-direction: column; gap: 8px; margin-bottom: 12px; max-height: 450px; overflow-y: auto; padding-right: 6px; }
  .config-row { display: flex; flex-direction: column; background: #070e07; padding: 6px 8px; border: 1px solid #113311; gap: 4px;}
  .config-row.inline { flex-direction: row; align-items: center; justify-content: space-between; }
  .config-label { color: #88cc88; font-weight: bold; font-size: 12px; min-width: 65px;}

  select, input[type="text"], input[type="number"] {
    background: #000; color: #55ff55; border: 1px solid #008800; padding: 4px 6px; font-family: monospace; outline: none; font-size: 12px; width: 100%; box-sizing: border-box;
  }
  .inline select { width: auto; flex: 1; margin-left: 8px; }
  select:focus, input:focus { box-shadow: 0 0 5px rgba(0,255,0,0.5); border-color: #00ff00;}
  ::placeholder { color: #005500; font-style: italic; }

  .custom-area { display: none; background: #020a02; border-left: 2px solid #00aa00; padding: 6px 8px; font-size: 11px; color: #00aa00; margin-top: 4px; gap: 4px; flex-direction: column;}
  .custom-row { display: flex; align-items: center; gap: 4px; margin-bottom: 2px;}
  .eval-text { color: #ff5555; font-weight: bold; margin-left: 6px; text-shadow: 0 0 2px #aa0000; font-size: 10px;}

  .bwh-grid { display: flex; flex-direction: column; gap: 4px; }
  .bwh-item { display: flex; align-items: center; gap: 6px; }
  .bwh-item input { width: 80px; text-align: center; padding: 2px; }

  .btn-generate { width: 100%; padding: 12px; background: linear-gradient(to bottom, #115511, #052205); border: 2px solid #000; color: #55ff55; font-weight: bold; font-size: 15px; letter-spacing: 2px; cursor: pointer; box-shadow: 0 4px 0 #000, 0 5px 10px rgba(0,0,0,0.6); }
  .btn-generate:active { transform: translateY(4px); box-shadow: 0 0 0 #000; }
  </style>

  <script type="module">
    let selectedMeatId = null;

    window.fillCommand = function(text) {
      let textarea = null;
      try {
        textarea = window.parent.document.getElementById('send_textarea') || window.parent.document.getElementById('chat_input_textarea');
      } catch (e) { console.error(e); }
      if (textarea) {
        textarea.value += (textarea.value ? '\n' : '') + text;
        textarea.focus();
        textarea.dispatchEvent(new Event('input', { bubbles: true }));
        textarea.dispatchEvent(new Event('change', { bubbles: true }));
        if (typeof toastr !== 'undefined') toastr.info(`指令已注入终端...`);
      }
    };

    window.switchTab = function(tabId) {
      $('.tab').removeClass('active');
      $('.tab-content').removeClass('active');
      $(`.tab[onclick="switchTab('${tabId}')"]`).addClass('active');
      $(`#${tabId}`).addClass('active');
    };

    function bindCustomToggle(selectId, areaId) {
      $(document).on('change', `#${selectId}`, function() {
        if ($(this).val() === '自定义') {
          $(`#${areaId}`).css('display', 'flex');
        } else {
          $(`#${areaId}`).hide();
        }
      });
    }

    $(document).on('change', '#sel-race', function() {
      const val = $(this).val();
      if (val === '人类') { $('#sub-demi').hide(); }
      else {
        $('#sub-demi').css('display', 'flex');
        $('#input-demi').attr('placeholder', val === '强体能型亚人' ? '如：狼娘、马娘...' : '如：兔娘、猫娘...');
      }
    });

    bindCustomToggle('sel-hw', 'custom-hw');
    bindCustomToggle('sel-wh', 'custom-wh');
    bindCustomToggle('sel-hair-len', 'custom-hair-len');
    bindCustomToggle('sel-hair-color', 'custom-hair-color');
    bindCustomToggle('sel-eye', 'custom-eye');
    bindCustomToggle('sel-cup', 'custom-cup');
    bindCustomToggle('sel-boobs', 'custom-boobs');
    bindCustomToggle('sel-nipple', 'custom-nipple');
    bindCustomToggle('sel-areola', 'custom-areola');
    bindCustomToggle('sel-hole', 'custom-hole');
    bindCustomToggle('sel-trait', 'custom-trait');
    bindCustomToggle('sel-flaw', 'custom-flaw');

    // 自动评估逻辑：极限身高与体重
    $(document).on('input', '#inp-h', function() {
      const v = parseInt($(this).val());
      let ev = '';
      if(!isNaN(v)){
        if(v < 130) $(this).val(130);
        else if(v > 300) $(this).val(300);
        const curV = parseInt($(this).val());
        if(curV < 145) ev = '[极端侏儒/幼体]';
        else if(curV <= 160) ev = '[娇小]';
        else if(curV <= 175) ev = '[匀称适中]';
        else if(curV <= 200) ev = '[高大重坠]';
        else ev = '[亚人巨物]';
      }
      $('#eval-h').text(ev);
    });

    $(document).on('input', '#inp-w', function() {
      const v = parseFloat($(this).val());
      let ev = '';
      if(!isNaN(v)){
        if(v < 20) $(this).val(20);
        else if(v > 200) $(this).val(200);
        const curV = parseFloat($(this).val());
        if(curV < 35) ev = '[骨瘦如柴/发育极差]';
        else if(curV <= 50) ev = '[纤细]';
        else if(curV <= 70) ev = '[匀称肉感]';
        else if(curV <= 100) ev = '[肥胖重坠]';
        else ev = '[极端巨兽/超重病态]';
      }
      $('#eval-w').text(ev);
    });

    // 腰围臀围
    $(document).on('input', '#inp-w2', function() {
      const v = parseInt($(this).val());
      let ev = '';
      if(!isNaN(v)){
        if(v < 40) $(this).val(40);
        else if(v > 150) $(this).val(150);
        const curV = parseInt($(this).val());
        if(curV < 50) ev = '[极端骨感]';
        else if(curV <= 60) ev = '[纤细盈握]';
        else if(curV <= 70) ev = '[标准腰围]';
        else if(curV <= 85) ev = '[丰腴肉感]';
        else if(curV <= 100) ev = '[宽腰粗壮]';
        else ev = '[严重脂肪堆积]';
      }
      $('#eval-w2').text(ev);
    });

    $(document).on('input', '#inp-h2', function() {
      const v = parseInt($(this).val());
      let ev = '';
      if(!isNaN(v)){
        if(v < 70) $(this).val(70);
        else if(v > 200) $(this).val(200);
        const curV = parseInt($(this).val());
        if(curV < 80) ev = '[干瘪窄臀]';
        else if(curV <= 90) ev = '[紧致小巧]';
        else if(curV <= 100) ev = '[圆润挺翘]';
        else if(curV <= 115) ev = '[丰乳肥臀]';
        else if(curV <= 135) ev = '[重度脂肪重坠]';
        else ev = '[极端畸形宽大]';
      }
      $('#eval-h2').text(ev);
    });

    // 孔道深度
    $(document).on('input', '#inp-v', function() {
      const v = parseInt($(this).val());
      let ev = '';
      if(!isNaN(v)){
        if(v < 5) $(this).val(5);
        else if(v > 40) $(this).val(40);
        const curV = parseInt($(this).val());
        if(curV < 14) ev = '[极度紧致极浅]';
        else if(curV <= 18) ev = '[常规深度]';
        else ev = '[已被扩充/深谷]';
      }
      $('#eval-v').text(ev);
    });

    $(document).on('input', '#inp-a', function() {
      const v = parseInt($(this).val());
      let ev = '';
      if(!isNaN(v)){
        if(v < 5) $(this).val(5);
        else if(v > 50) $(this).val(50);
        const curV = parseInt($(this).val());
        if(curV < 15) ev = '[未经开发浅洞]';
        else if(curV <= 20) ev = '[常规使用]';
        else ev = '[重度扩充外翻]';
      }
      $('#eval-a').text(ev);
    });

    window.generateMeat = function() {
      let race = $('#sel-race').val();
      if (race !== '人类') {
        const demi = $('#input-demi').val().trim();
        if (demi) race = `${race}(${demi})`;
      }

      const body = $('#sel-body').val();
      const skin = $('#sel-skin').val();
      const pussy = $('#sel-pussy').val();
      const mode = $('#sel-mode').val();

      let hw = $('#sel-hw').val();
      if (hw === '自定义') hw = `悬吊长${$('#inp-h').val() || '?'}cm${$('#eval-h').text()} / 净重${$('#inp-w').val() || '?'}kg${$('#eval-w').text()}`;

      // 三围被拆解为罩杯形态与腰臀数据
      let cup = $('#sel-cup').val();
      if (cup === '自定义') cup = $('#input-cup').val() || '未设定罩杯';
      let boobsShape = $('#sel-boobs').val();
      if (boobsShape === '自定义') boobsShape = $('#input-boobs').val() || '未设定乳房形态';

      let wh = $('#sel-wh').val();
      if (wh === '自定义') wh = `W${$('#inp-w2').val() || '?'} ${$('#eval-w2').text()} - H${$('#inp-h2').val() || '?'} ${$('#eval-h2').text()}`;

      let hairLen = $('#sel-hair-len').val();
      if (hairLen === '自定义') hairLen = $('#input-hair-len').val() || '未设定长度';

      let hairColor = $('#sel-hair-color').val();
      if (hairColor === '自定义') hairColor = $('#input-hair-color').val() || '未设定发色';

      let eye = $('#sel-eye').val();
      if (eye === '自定义') eye = $('#input-eye').val() || '未设定瞳色';

      let nipple = $('#sel-nipple').val();
      if (nipple === '自定义') nipple = $('#input-nipple').val() || '未设定乳头';

      let areola = $('#sel-areola').val();
      if (areola === '自定义') areola = $('#input-areola').val() || '未设定乳晕';

      let hole = $('#sel-hole').val();
      if (hole === '自定义') hole = `阴道深${$('#inp-v').val() || '?'}cm${$('#eval-v').text()} / 肛门深${$('#inp-a').val() || '?'}cm${$('#eval-a').text()}`;

      let trait = $('#sel-trait').val();
      if (trait === '自定义') trait = $('#input-trait').val() || '未设定活体特征';

      let flaw = $('#sel-flaw').val();
      if (flaw === '自定义') flaw = $('#input-flaw').val() || '未设定体表瑕疵';

      let cmd = `[来到女肉生成机终端前，输入参数：
种族品种：${race}
体型年龄：${body}
身高净重：${hw}
胸部乳房：${cup}罩杯 / ${boobsShape} / 乳头：${nipple} / 乳晕：${areola}
腰围臀围：${wh}
肤色质感：${skin}
发色瞳色：${hairColor}${hairLen} / ${eye}
私处外观：${pussy}
孔道数据：${hole}
活体特征：${trait}
体表瑕疵：${flaw}
选择运作模式：${mode}，拉下拉杆开始生产]`;

      fillCommand(cmd);
      if (typeof toastr !== 'undefined') toastr.success('出货单已准备。');
    };

    window.selectMeat = function(id) {
      if (selectedMeatId === id) {
        selectedMeatId = null;
        $('.meat-card').removeClass('selected');
        $('#selected-target').text('未选中');
      } else {
        selectedMeatId = id;
        $('.meat-card').removeClass('selected');
        $(`#meat-${id}`).addClass('selected');
        $('#selected-target').text(`NO.${id}`);
      }
    };

    window.doAction = function(actionDesc) {
      if (!selectedMeatId) {
        if (typeof toastr !== 'undefined') toastr.error('未锁定目标！请先在防水布上选中一块肉。');
        return;
      }
      fillCommand(`[在防水布摊位上抓起出厂编号为 ${selectedMeatId} 的女肉，对她进行：${actionDesc}]`);
    };

    function populateData() {
      const all_vars = _.get(getAllVariables(), 'stat_data', {});
      const meatList = _.get(all_vars, '现有女奴清单', {});
      const plugList = _.get(all_vars, '人格排泄物清单', {});

      const tarpContainer = $('#tarp-list');
      const rackContainer = $('#rack-list');
      tarpContainer.empty();
      rackContainer.empty();

      if (Object.keys(meatList).length === 0) {
        tarpContainer.html('<div style="color:#555; text-align:center; padding:15px; font-style:italic;">防水布上空无一物，连血水都被冲干了。</div>');
      } else {
        Object.entries(meatList).forEach(([id, data]) => {
          const isSelected = selectedMeatId === id ? 'selected' : '';
          const html = `
            <div id="meat-${id}" class="meat-card ${isSelected}" onclick="selectMeat('${id}')">
              <div class="meat-header">
                <span>NO.${id}</span>
                <span class="meat-status">${data.包装状态 || '待机中'}</span>
              </div>
              <div class="meat-info">
                <div class="info-line">
                  <span><span class="info-label">品种:</span> ${data.种族品种 || '无'}</span> |
                  <span><span class="info-label">体型:</span> ${data.体型年龄 || '无'}</span> |
                  <span><span class="info-label">肤质:</span> ${data.肤色质感 || '无'}</span>
                </div>
                <div class="info-line">
                  <span><span class="info-label">规格:</span> ${data.三围数据 || '无'}</span> |
                  <span><span class="info-label">乳房:</span> ${data.乳房形态 || '无'}</span> |
                  <span><span class="info-label">孔道:</span> ${data.孔道数据 || '无'}</span>
                </div>
                <div class="info-line" style="border-bottom:none;">
                  <span><span class="info-label">加工状态:</span> ${data.特殊处理 || '无'}</span> |
                  <span><span class="info-label">瑕疵:</span> <span style="color:#8b0000;">${data.体表瑕疵 || '无'}</span></span>
                </div>
              </div>
            </div>
          `;
          tarpContainer.append(html);
        });
      }

      let plugCount = 0;
      Object.entries(plugList).forEach(([id, pData]) => {
        plugCount++;
        rackContainer.append(`
          <div class="plug-item">
            <span>绑定:[NO.${id.substring(0,4)}..]</span>
            <span>${pData.加工成品 || '未知器具'}</span>
          </div>
        `);
      });
      if (plugCount === 0) {
        rackContainer.html('<div style="color:#664433; text-align:center; font-style:italic; font-size:12px; padding: 4px;">铁丝网上空荡荡，没有悬挂配件。</div>');
      }

      if (selectedMeatId && !meatList[selectedMeatId]) {
        selectedMeatId = null;
        $('#selected-target').text('未选中');
      } else if (selectedMeatId) {
        $('#selected-target').text(`NO.${selectedMeatId}`);
      }
    }

    async function init() {
      await waitGlobalInitialized('Mvu');
      populateData();
      eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, () => { populateData(); });
    }

    $(errorCatched(init));
  </script>
</head>
<body>
  <div class="market-container">

    <div class="top-bar">
      <div class="title-neon">M.E.A.T. 后台管控</div>
      <div>
        <button class="btn btn-gray" style="padding:4px 8px;" onclick="fillCommand('[巡视整个市场摊位，观察是否有买家驻足]')">👁 巡视摊位</button>
      </div>
    </div>

    <div class="tabs">
      <div class="tab active" onclick="switchTab('tab-tarp')">防水布地摊</div>
      <div class="tab" onclick="switchTab('tab-machine')">活体生成终端</div>
