        <div class="btn-grid">
          <button class="btn btn-gray" onclick="doAction('打印活体检疫证明，确认外观锚点')">🖨 打印检疫吊牌</button>
          <button class="btn btn-gray" onclick="doAction('在腹部用粗笔画上深度刻度与试用涂鸦')">🖍 售前人体涂鸦</button>
          <button class="btn btn-blue" onclick="doAction('用冷水管高压冲洗并刮除全部体毛')">🚿 彻底清洗除毛</button>
          <button class="btn btn-blue" onclick="doAction('用口红涂抹孔道边缘，在纸上按压拓印纹理')">💋 强制孔道拓印</button>
          <button class="btn btn-blue" onclick="doAction('使用烧红的金属字模，在皮肤上打上名器烙印')">🔥 高温破坏烙印</button>
          <button class="btn btn-blue" onclick="doAction('在其阴户贴上宽胶带与封印纸，彻底封死小穴')">🏷 处女胶带封穴</button>

          <!-- 新增排出和注入按钮，细分加工方式 -->
          <button class="btn btn-purple" onclick="doAction('强行灌注凝胶抽出人格核心，并加工制成粗大的柱状肛塞')">⚙ 抽出人格制成肛塞</button>
          <button class="btn btn-purple" onclick="doAction('强行灌注凝胶抽出人格核心，并加工制成长条深喉口塞')">⚙ 抽出人格制成口塞</button>
          <button class="btn btn-red" style="grid-column: span 2;" onclick="doAction('将原配的人格制品粗暴捅入其深处，短暂唤醒意识进行活体折磨')">⚙ 注入人格短暂唤醒折磨</button>

          <button class="btn btn-yellow" onclick="doAction('用木枷锁住上半身，强行揉捏乳房榨取鲜乳')">🥛 木枷榨取鲜乳</button>
          <button class="btn btn-yellow" onclick="doAction('用漏斗水管，向胃部膀胱强制注水至膨胀极限')">💦 极限高压注水</button>
          <button class="btn btn-red" style="grid-column: span 2;" onclick="doAction('折叠塞入铺满碎冰的泡沫盒，倒催情液死死封箱打包')">📦 塞入冰块泡沫箱密封打包</button>
        </div>
      </div>
    </div>

    <!-- TAB 2: 终端生成机 -->
    <div id="tab-machine" class="tab-content">
      <div class="terminal-box">
        <div class="screen">
          <div style="color:#55ff55; border-bottom:1px dashed #005500; padding-bottom:4px; margin-bottom:8px;">▶ M.E.A.T. SYNTHESIZER V3.6</div>
          <div>等待录入细胞培养锚点...</div>
        </div>

        <div class="config-list">

          <div class="config-row inline">
            <span class="config-label">种族：</span>
            <select id="sel-race">
              <option value="人类">人类</option>
              <option value="弱体能型亚人">弱体能型亚人</option>
              <option value="强体能型亚人">强体能型亚人</option>
