import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';

export const Schema = z.object({
  现有女奴清单: z.record(
    z.string().describe('出厂编号'),
    z.object({
      种族品种: z.string().prefault('未记录'),
      体型年龄: z.string().prefault('未记录'),
      身高净重: z.string().prefault('未记录'),
      三围数据: z.string().prefault('未记录'),
      肤色质感: z.string().prefault('未记录'),
      发色瞳色: z.string().prefault('未记录'),
      乳房形态: z.string().prefault('未记录'),
      私处外观: z.string().prefault('未记录'),
      孔道数据: z.string().prefault('未记录'),
      活体特征: z.string().prefault('未记录'),
      体表瑕疵: z.string().prefault('未记录'),
      特殊处理: z.string().prefault('未记录'),
      包装状态: z.string().prefault('未挂牌')
    })
  ),

  人格排泄物清单: z.record(
    z.string().describe('对应女肉的出厂编号'),
    z.object({
      物理状态: z.string().prefault('带着体温的半透明粘稠液'),
      加工成品: z.string().prefault('粗大的柱状肛塞')
    })
  )
});

$(() => {
  registerMvuSchema(Schema);
})

entries.content:
---
变量更新规则:
  现有女奴清单:
    type: |-
      {
        [出厂编号: string]: {
          种族品种: string;
          体型年龄: string;
          身高净重: string;
          三围数据: string;
          肤色质感: string;
          发色瞳色: string;
          乳房形态: string;
          私处外观: string;
          孔道数据: string;
          活体特征: string;
          体表瑕疵: string;
          特殊处理: string;
          包装状态: string;
        }
      }
    check:
      - 当购入新货或女肉生成机产出新商品时，立刻创建新的出厂编号条目，并客观详尽地录入该活体的所有锚点参数。
      - 基础外貌与解剖参数（如三围、肤色、瞳色、种族等）录入后锁定，不可随意更改，除非躯体遭遇不可逆的极端物理破坏。
      - 当躯体遭受买家活体试用、暴力检视、留下涂鸦留言或造成伤痕时，及时更新【体表瑕疵】与【孔道数据】（例如记录被撑开或失禁的状态）。
      - 当摊主进行打标、清洗除毛、封穴、鲜榨或装入礼盒等操作时，及时更新【特殊处理】与【包装状态】。
      - 若商品被售出并带离市场，可将其从清单中移除，或将包装状态更新为“已售出”。

  人格排泄物清单:
    type: |-
      {
        [对应女肉的出厂编号: string]: {
          物理状态: string;
          加工成品: string;
        }
      }
    check:
      - 当女肉经历人格排泄程序、抽出精神核心时录入。使用的键名（出厂编号）必须与《现有女奴清单》中的编号严格绑定对应。
      - 客观记录排出物最初的粘稠度、颜色等物理状态，以及最终加工凝固成的器械制式（如长条肛塞、深喉口塞等）。
      - 作为女肉的原装配件，此清单内容一旦录入便作为防伪标识，通常不再发生变更。
